public class Product {
    private String name;
    private double price;
    private String category;

    // Use 1: Field disambiguation
    public Product(String name, double price) {
        this.name = name;     // this.name is field, name is parameter
        this.price = price;
        this.category = "General";
    }

    // Use 2: Constructor chaining
    public Product(String name, double price, String category) {
        this(name, price);    // Calls the two-arg constructor above
        this.category = category;
    }

    // Use 3: Passing current object reference
    public Product applyDiscount(double percent) {
        this.price = this.price * (1 - percent / 100);
        return this;          // Returns current object for method chaining
    }

    public void logToAudit(AuditService audit) {
        audit.recordChange(this);  // Passes current Product to service
    }
}
