public class Product {
    private String name;           // Instance field - one per object
    private static int count = 0;  // Static field - shared by all

    public Product(String name) {
        this.name = name;          // OK: constructor has 'this'
        count++;                   // OK: can access static from instance
    }

    // Instance method - has access to 'this'
    public void updateName(String newName) {
        this.name = newName;       // OK: 'this' available
        incrementCount();          // OK: can call static from instance
    }

    // Static method - NO access to 'this' or instance members
    public static int getCount() {
        return count;              // OK: accessing static field
        // return this.name;       // COMPILE ERROR: 'this' not available
        // updateName("test");     // COMPILE ERROR: can't call instance method
    }

    private static void incrementCount() {
        count++;
        // this.name = "test";     // COMPILE ERROR: no 'this' in static
    }
}
