class Order {
    protected double totalAmount;
    protected List<String> auditLog = new ArrayList<>();

    public void finalizeOrder() {
        validateOrder();           // Critical validation
        auditLog.add("Order finalized at " + LocalDateTime.now());
        totalAmount = calculateTotal();
    }

    protected double calculateTotal() {
        return totalAmount;        // Base implementation
    }

    protected void validateOrder() {
        if (totalAmount < 0) throw new IllegalStateException("Invalid amount");
    }
}

class SubscriptionOrder extends Order {
    private double recurringDiscount = 0.15;

    @Override
    protected double calculateTotal() {
        double baseTotal = super.calculateTotal();  // Keep parent logic
        return baseTotal * (1 - recurringDiscount); // Add discount
    }

    // If we forgot super.validateOrder(), we'd lose validation
    @Override
    protected void validateOrder() {
        super.validateOrder();     // Keep parent's amount check
        if (recurringDiscount > 0.5) throw new IllegalStateException("Discount too high");
    }
}
