public class Customer {
    private String name;
    private String email;
    private String phone;

    // Most complete constructor - calls super() implicitly
    public Customer(String name, String email, String phone) {
        // Java inserts invisible super() here
        this.name = name;
        this.email = email;
        this.phone = phone;
    }

    // Delegates to three-arg constructor using this()
    public Customer(String name, String email) {
        this(name, email, null);  // this() must be first
    }

    // Delegates to two-arg constructor
    public Customer(String name) {
        this(name, "noemail@example.com");  // Chains to above
    }

    // ERROR: Can't have both
    // public Customer(String name) {
    //     super();        // Can't be here
    //     this(name, ""); // Can't be here either - both need first spot
