```java
class Customer {
    protected double baseDiscount = 5.0;

    public void processOrder(Order order) {
        double discount = this.calculateDiscount();  // Calls overridden version
        System.out.println("Applying " + discount + "% discount");
        order.applyDiscount(discount);
    }

    protected double calculateDiscount() {
        return baseDiscount;
    }
}

class PremiumCustomer extends Customer {
    @Override
    protected double calculateDiscount() {
        return baseDiscount + 10.0;  // Premium gets extra 10%
    }
}

var customer = new PremiumCustomer();
customer.processOrder(order);
// Output: "Applying 15.0% discount"
// Even though processOrder is in Customer, this.calculateDiscount()
// executes the PremiumCustomer version because that's the actual object type
